import '../../../core/network/api_client.dart';import 'doctor_models.dart';class DoctorRepository{DoctorRepository(this._client);final ApiClient _client;Future<List<DoctorPatient>>patients()async{final r=await _client.dio.get<List<dynamic>>('/api/doctor-dashboard/patients');return r.data!.map((e)=>DoctorPatient.fromJson(e)).toList();}Future<DoctorPatientDetails>details(String id)async{final r=await _client.dio.get<Map<String,dynamic>>('/api/doctor-patients/'+id);return DoctorPatientDetails.fromJson(r.data!);}}